          "w": 692,
          "h": 360
        }
      },
      {
        "item": "viz_21",
        "type": "block",
        "position": {
          "x": 728,
          "y": 870,
          "w": 692,
          "h": 360
        }
      },
      {
        "item": "viz_23",
        "type": "block",
        "position": {
          "x": 20,
          "y": 1246,
          "w": 1400,
          "h": 320
        }
      }
    ],
    "globalInputs": [
      "input_time"
    ]
  }
}
